'use strict';

// MODULES //

var constantFunction = require( '@stdlib/utils/constant-function' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var ln = require( '@stdlib/math/base/special/ln' );
var log1p = require( '@stdlib/math/base/special/log1p' );
var NINF = require( '@stdlib/constants/float64/ninf' );


// MAIN //

/**
* Returns a function for evaluating the logarithm of the probability density function (logPDF) for a Bradford distribution with shape parameter `c`.
*
* @param {PositiveNumber} c - shape parameter
* @returns {Function} logPDF
*
* @example
* var logpdf = factory( 5.0 );
* var y = logpdf( 0.5 );
* // returns ~-0.227
*
* y = logpdf( 1.0 );
* // returns ~-0.766
*/
function factory( c ) {
	var k;
	if ( isnan( c ) || c <= 0.0 ) {
		return constantFunction( NaN );
	}
	k = log1p( c );
	return logpdf;

	/**
	* Evaluates the logarithm of the probability density function (logPDF) for a Bradford distribution.
	*
	* @private
	* @param {number} x - input value
	* @returns {number} evaluated logPDF
	*
	* @example
	* var y = pdf( 0.5 );
	* // returns <number>
	*/
	function logpdf( x ) {
		if ( isnan( x ) ) {
			return NaN;
		}
		if ( x < 0.0 || x > 1.0 ) {
			return NINF;
		}
		return ln( c ) - ln( 1.0 + ( c*x ) ) - ln( k );
	}
}


// EXPORTS //

module.exports = factory;
